examples:
TypeScript example (async generator):
const gen = WindowedBatcher(inputs, {maxInFlight: 6, targetTokenSize: 4096});
for await (const batch of gen) {
  const resp = await client.embeddings.create({input: batch});
  yield* resp.data;
}

Go example (channels):
ctx, cancel := context.WithCancel(context.Background())
batches, errs := windowedbatcher.Chunks(ctx, inputs, windowedbatcher.Config{MaxInFlight:6, TargetTokenSize:4096})
for {
  select {
  case b, ok := <-batches: if !ok { return }
    resp := client.Embeddings(ctx, b.Items)
    // process resp
  case err := <-errs: // handle error
  }
}
